import random
import string
from typing import List

# Target format: space-separated name=value options string
# Names: [A-Za-z0-9_-]+, Values: arbitrary but avoid quotes/newlines per stub sanitizer.
# The fuzzer stub uses two FUZZ_PARAM_STR() to build:
#   name=value opt_on=on opt_empty=""
# Our buffer should provide interesting pairs that, after sanitization, remain varied.

SAFE_NAME_CHARS = string.ascii_letters + string.digits + "_-"
SAFE_VALUE_CHARS = (
    string.ascii_letters + string.digits + "_-.:,/@#%+*=()[]{}|^~" + " "
)

BOOLEAN_VALUES = ["1", "0", "yes", "no", "true", "false", "on", "off", "", "YeS", "FaLsE"]

# Some common DB-like option names to exercise code paths.
COMMON_OPTION_NAMES = [
    "host", "port", "user", "password", "dbname", "service", "sslmode",
    "connect_timeout", "application_name", "schema", "encoding",
    "readonly", "autocommit", "keepalive", "binary_transfer",
]

SSL_VALUES = ["disable", "allow", "prefer", "require", "verify-ca", "verify-full"]


def _rand_name(rng: random.Random) -> str:
    # Prefer known names sometimes to hit get_option/has_option/use-cases.
    if rng.random() < 0.6:
        base = rng.choice(COMMON_OPTION_NAMES)
        # Occasionally add suffix/prefix to create unique keys
        if rng.random() < 0.3:
            base += "_" + rng.choice(["A", "B", "C", "x", "y", "z"]) \
                    + str(rng.randint(0, 9))
        return base
    # Otherwise generate a random safe name
    length = rng.randint(1, 12)
    return ''.join(rng.choice(SAFE_NAME_CHARS) for _ in range(length))


def _rand_value(rng: random.Random, name: str) -> str:
    # Provide semantically meaningful values for some names
    lname = name.lower()
    if lname in ("port", "connect_timeout", "keepalive"):
        return str(rng.choice([0, 1, 5, 10, 30, 60, 5432, 1521, 3306]))
    if lname in ("sslmode",):
        return rng.choice(SSL_VALUES)
    if lname in ("readonly", "autocommit", "binary_transfer"):
        return rng.choice(BOOLEAN_VALUES)
    if lname in ("host", "service"):
        hosts = [
            "localhost", "127.0.0.1", "::1", "db", "example.com",
            "socket:/var/run/postgresql", "unix:/tmp/.s.PGSQL.5432",
        ]
        return rng.choice(hosts)
    if lname in ("user", "dbname", "schema", "application_name", "encoding"):
        candidates = [
            "user", "root", "postgres", "app", "test", "ci", "äccént",
            "public", "main", "UTF8", "LATIN1"
        ]
        return rng.choice(candidates)
    if lname == "password":
        # Include characters that are safe per stub sanitizer (quotes become _ later)
        pw_chars = string.ascii_letters + string.digits + "_-.:@#%+*="
        return ''.join(rng.choice(pw_chars) for _ in range(rng.randint(6, 16)))

    # Otherwise random safe string, with occasional spaces
    length = rng.randint(0, 24)
    if length == 0:
        return ""
    s = ''.join(rng.choice(SAFE_VALUE_CHARS) for _ in range(length))
    # Trim leading/trailing spaces to avoid ambiguity
    return s.strip()


def _compose_options(rng: random.Random) -> str:
    # Ensure at least one syntactically valid name=value at the start
    tokens: List[str] = []

    # Primary pair likely to be used by the stub to construct raw1=raw2
    n_primary = _rand_name(rng)
    v_primary = _rand_value(rng, n_primary)
    tokens.append(f"{n_primary}={v_primary}")

    # Add a spread of additional options
    count = rng.randint(3, 10)
    used = {n_primary}
    for _ in range(count):
        name = _rand_name(rng)
        if name in used:
            name += "_" + str(rng.randint(0, 9))
        used.add(name)
        val = _rand_value(rng, name)
        # Occasionally quote values that contain spaces to exercise parser
        if (" " in val) and rng.random() < 0.7:
            # Quote with double-quotes; the parser supports quoted values
            q = '"' + val.replace('"', '') + '"'
            val = q
        tokens.append(f"{name}={val}")

    # Explicitly include booleans to hit is_true_value paths
    tokens.append("opt_on=on")
    tokens.append("opt_off=off")
    tokens.append('opt_empty=""')

    # Shuffle to vary order
    rng.shuffle(tokens)

    # Join with single spaces
    return " ".join(tokens)


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    # Build an interesting, syntactically valid space-separated options string
    s = _compose_options(rng)
    # Cap length to <= 4096 bytes
    if len(s) > 4096:
        s = s[:4096]
    return s.encode('utf-8')
